<script setup>
import {computed,ref,onMounted,onUnmounted} from 'vue'
import request from '../api/request.js'
import {useDecisionResearch} from './useDecisionResearch.js'
import VersionComparison from './VersionComparison.vue'
import ResearchDataCharts from './ResearchDataCharts.vue'
import {marketChartBlocks} from '../utils/decisionChartOptions.js'
const props=defineProps({id:String})
const developer=new URLSearchParams(location.search).get('developer')==='1'
const {state,history,error,loading,submitting,start,active,action,load,refresh}=useDecisionResearch(props.id,{navigate:id=>{location.hash='#/market/'+id}})
const data=computed(()=>state.value?.data?.report?.stage==='P6_MARKET'?state.value.data:null)
const records=computed(()=>history.value.filter(r=>r.page==='market'&&(developer||r.status==='COMPLETED')))
const cache=ref([]),cacheError=ref('')
let disposed=false
onMounted(async()=>{try{const value=await request('/quant/decision/industry-cache');if(!disposed)cache.value=value}catch(e){if(!disposed)cacheError.value=e.message}})
onUnmounted(()=>{disposed=true})
const generate=()=>start({scope:'market',research_mode:'market_scan',entity:'设备与制造观察范围',question:'在明确覆盖范围内观察行业成交关注、广度和集中度，选择下一步研究方向。'})
const pct=v=>v==null?'窗口未齐':(Number(v)*100).toFixed(2)+'%'
const stamp=v=>new Date(v).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})
function industry(name){const url=new URL(location.href);url.searchParams.set('industry',name);url.hash='#/candidates';return url.pathname+url.search+url.hash}
</script>
<template>
  <div class="page market-page">
    <section class="panel rep-section"><div class="section-heading"><h1>从市场关注，找到研究方向</h1><span v-if="developer" class="tag">开发者视图</span></div><p class="prediction-lead">先看行业交易是否活跃、上涨是否扩散，再进入公司分析。</p><p class="condition-note">研究范围为半导体设备与集成电路制造。只比较已取得的范围，实际覆盖和日期以下方结果为准。</p><button class="btn btn-primary" :disabled="submitting||active(state)" @click="data?refresh():generate()">{{ submitting?'正在提交…':active(state)?'正在扫描…':data?'重新取数，另存市场观察':'扫描这两个行业' }}</button><p v-if="loading&&!state" role="status">正在读取观察记录…</p><p v-if="error" role="alert" class="error-text">{{ error }} <button class="btn" @click="load">重新读取</button></p></section>
    <section v-if="active(state)" class="panel rep-section" aria-live="polite"><h2>正在核对市场资料</h2><p>{{ developer ? state.process.at(-1)?.detail : '正在核对市场、行业与资金数据…' }}</p><button class="btn" :disabled="submitting" @click="action('cancel')">停止扫描</button></section>
    <section v-if="state&&['FAILED','INTERRUPTED','CANCELLED'].includes(state.status)" class="panel rep-section"><h2>本次观察尚未完成</h2><p>{{ developer?state.error:'本次没有取得完整行业资料，未生成排序。失败记录已保留，可以重试或查看此前保存的研究。' }}</p><button v-if="state.status!=='CANCELLED'" class="btn" :disabled="submitting" @click="action('resume')">继续未完成步骤</button></section>
    <template v-if="data">
      <section class="panel rep-section"><h2>{{ data.metrics.length?'接下来，先看哪个行业':'当前市场观察' }}</h2><p class="market-conclusion">{{ data.report.summary }}</p><p class="condition-note">资料截止 {{ stamp(data.report.cutoff_at) }} · 行情 {{ data.heat_inputs?.sessions.at(-1) || data.market_index?.last_session }}<template v-if="data.coverage.members_total!=null"> · 共 {{ data.coverage.members_total }} 家成分，完整序列 {{ data.coverage.members_available }} 家</template><template v-else> · 行业成分数量尚未取得</template></p><p v-if="data.metrics.length" class="condition-note">只在本次两个行业范围内比较，不代表全市场排行；成交活跃不能直接解释为资金流入。</p></section>
      <section v-if="data.market_index" class="panel rep-section"><h2>沪深三百，近期实际怎么走</h2><div class="market-metrics"><section><span>近二十个交易日价格变化</span><strong>{{ pct(data.market_index.return_20) }}</strong></section><section><span>最近完整收盘</span><strong>{{ data.market_index.close }}</strong></section></div><p class="condition-note">{{ data.market_index.first_session }} — {{ data.market_index.last_session }}。来源为腾讯日行情，起始收盘 {{ data.market_index.base_close }}。这是近期价格观察，不是未来方向预测。</p><p class="notice">本次未生成行业排序。此前行业研究可在下方按保存日期回看。</p><a class="btn" :href="industry('半导体设备')">选择设备行业研究</a> <a class="btn" :href="industry('集成电路制造')">选择制造行业研究</a></section>
      <p v-if="data.coverage.membership_protocol" class="condition-note">成交占比按各交易日实际有效成员计算，行业范围始终为设备与制造。当前成员的完整价格窗口单独核对，新股上市前不计入当日成员，也不补造行情。</p>
      <VersionComparison :id="id" page="market"/>
      <section v-if="data.metrics.length" class="panel rep-section"><h2>两个行业，放在一起看</h2><ResearchDataCharts :blocks="marketChartBlocks(data.metrics)"/><p class="condition-note">成交占比的分母仅为本次两个行业；上涨比例、成交集中度不是预测概率。</p></section>
      <article v-for="(row,index) in data.metrics" :key="row.industry_id" class="panel rep-section market-industry"><div class="section-heading"><h2><span v-if="data.selection.ranking.length" class="market-index">0{{ index+1 }}</span>{{ row.name }}</h2><span class="tag">{{ row.available }}/{{ row.members_total }} 家序列完整</span></div><div class="market-metrics"><section v-if="row.last_turnover!=null"><span>最近完整交易日成交额</span><strong>{{ (Number(row.last_turnover)/1e8).toFixed(2) }} 亿元</strong></section><section><span>范围内二十日平均成交占比</span><strong>{{ pct(row.mean_20_share) }}</strong><div v-if="row.mean_20_share!=null" class="market-bar"><i :style="{width:Math.min(100,Number(row.mean_20_share)*100)+'%'}"/></div></section><section><span>近五日占比较前五日</span><strong>{{ row.change_5_share==null?'资料不足':(Number(row.change_5_share)*100).toFixed(2)+' 个百分点' }}</strong></section><section><span>二十日成员价格变化中位数</span><strong>{{ pct(row.median_member_return_20) }}</strong></section><section><span>最近一日上涨成员比例</span><strong>{{ pct(row.breadth) }}</strong></section><section><span>前三只成员的当日成交贡献</span><strong>{{ pct(row.top3_turnover_share) }}</strong></section></div><p class="condition-note">{{ row.name==='集成电路制造'?'制造研究重点：晶圆需求、产能利用率、工艺结构、资本开支与折旧。':'设备研究重点：客户资本开支、设备导入验收、经营兑现与回款。' }}</p><p v-for="gap in row.missing_reasons||[]" :key="gap.security_id" class="notice">{{ gap.security_id }}：{{ gap.reason }}。</p><p v-if="row.missing.length&&!row.missing_reasons?.length" class="notice">缺少完整窗口：{{ row.missing.join('、') }}。固定分母未缩小，未给出占比排序。</p><a class="btn btn-primary" :href="industry(row.name)">进入{{ row.name }}候选研究</a></article>
      <section class="panel rep-section"><details><summary>这次覆盖了哪里，还有哪些未接入</summary><p>{{ data.coverage.scope_note }}</p><p>{{ data.coverage.catalog_note }}</p><p v-if="data.coverage.data_source">来源：{{ data.coverage.data_source }} · 分类：{{ data.coverage.classification }} · 行情日期：{{ data.coverage.data_date }}。{{ data.coverage.cache_policy }}</p><p v-if="data.coverage.excluded_market_members?.length">明确未纳入本期范围：{{ data.coverage.excluded_market_members.map(r=>r.name+'（'+r.security_id+'）').join('、') }}。</p><p>没有完整窗口时不补零，不更换排名定义。按二十日平均占比、五日占比变化、行业 ID 排序；同一股票不会重复计入固定联合分母。</p><p class="market-unconnected">{{ data.coverage.unconnected.map(r=>r.industry_name||r.f14).join('、') }}</p></details></section>
      <section class="panel rep-section"><a class="btn" :href="'/api/quant/decision/runs/'+id+'/export'" target="_blank" rel="noopener noreferrer">导出这次观察</a><details v-if="developer" class="market-development"><summary>开发核验：成分、分母、选择记录与来源</summary><pre>{{ JSON.stringify({selection:data.selection,heat_inputs:data.heat_inputs,membership:data.membership,dated_membership:data.dated_membership,coverage:data.coverage,calls:state.calls,elapsed_seconds:state.elapsed_seconds},null,2) }}</pre></details></section>
    </template>
    <details v-if="records.length" class="panel rep-section research-history"><summary>已保存的市场观察 · {{ records.length }} 份</summary><a v-for="row in records" :key="row.run_id" class="prediction-history" :href="'#/market/'+row.run_id">{{ row.title }} · {{ stamp(row.created_at) }}</a></details>
    <section v-if="cache.length||cacheError" class="panel rep-section"><h2>此前保存的行业研究</h2><p class="condition-note">以下是有日期的归档研究。当前行情与成分仍需重新核对。</p><p v-if="cacheError" role="alert">{{ cacheError }}</p><a v-for="item in cache" :key="item.run_id" class="prediction-history" :href="'#/candidates/'+item.run_id">{{ item.entity }} · {{ stamp(item.cutoff_at) }} · {{ item.freshness==='STALE'?'资料已较旧':'近期保存，尚未重新核查' }}</a></section>
  </div>
</template>
<style scoped>.market-page .panel{margin-bottom:20px}.market-page p{line-height:1.9}.market-conclusion{font-size:19px}.market-index{color:var(--accent);margin-right:18px}.market-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:26px;margin:28px 0}.market-metrics section{border-top:1px solid var(--border);padding-top:15px}.market-metrics span{font-size:12px;color:var(--text-2)}.market-metrics strong{display:block;font-size:23px;margin:12px 0;font-weight:500}.market-bar{height:4px;background:var(--border)}.market-bar i{display:block;height:100%;background:var(--accent)}.market-page pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:60vh;overflow:auto}.market-page details{line-height:1.9;margin:18px 0}.market-unconnected{max-height:200px;overflow:auto}.market-page :is(a,button,summary):focus-visible{outline:2px solid var(--accent);outline-offset:4px}@media(max-width:700px){.market-metrics{grid-template-columns:1fr 1fr;gap:18px}.market-page .section-heading{flex-wrap:wrap;gap:12px}.market-conclusion{font-size:17px}.market-metrics strong{font-size:19px}}</style>
